      json[r'suggestionCount'] = null;
    }
    if (this.textToSpeechProvider != null) {
      json[r'textToSpeechProvider'] = this.textToSpeechProvider;
    } else {
      json[r'textToSpeechProvider'] = null;
    }
    if (this.themeColor != null) {
      json[r'themeColor'] = this.themeColor;
    } else {
      json[r'themeColor'] = null;
    }
    if (this.title != null) {
      json[r'title'] = this.title;
    } else {
      json[r'title'] = null;
    }
    if (this.vectorStoreId != null) {
      json[r'vectorStoreId'] = this.vectorStoreId;
    } else {
      json[r'vectorStoreId'] = null;
    }
      json[r'vectorStores'] = this.vectorStores;
    if (this.welcome != null) {
      json[r'welcome'] = this.welcome;
    } else {
      json[r'welcome'] = null;
    }
    if (this.welcomeText != null) {
      json[r'welcomeText'] = this.welcomeText;
    } else {
      json[r'welcomeText'] = null;
    }
    if (this.welcomeTitle != null) {
      json[r'welcomeTitle'] = this.welcomeTitle;
    } else {
      json[r'welcomeTitle'] = null;
    }
    return json;
  }

  /// Returns a new [Store] instance and imports its values from
  /// [value] if it's a [Map], null otherwise.
  // ignore: prefer_constructors_over_static_methods
  static Store? fromJson(dynamic value) {
    if (value is Map) {
      final json = value.cast<String, dynamic>();

      // Ensure that the map contains the required keys.
      // Note 1: the values aren't checked for validity beyond being non-null.
      // Note 2: this code is stripped in release mode!
      assert(() {
        requiredKeys.forEach((key) {
          assert(json.containsKey(key), 'Required key "Store[$key]" is missing from JSON.');
          assert(json[key] != null, 'Required key "Store[$key]" has a null value in JSON.');
        });
        return true;
      }());

      return Store(
        agentProvider: mapValueOfType<String>(json, r'agentProvider'),
        avatar: mapValueOfType<String>(json, r'avatar'),
        builtinTools: json[r'builtinTools'] is Iterable
            ? (json[r'builtinTools'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        chatCount: mapValueOfType<int>(json, r'chatCount'),
        childModelProviders: json[r'childModelProviders'] is Iterable
            ? (json[r'childModelProviders'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        childStores: json[r'childStores'] is Iterable
            ? (json[r'childStores'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        createdTime: mapValueOfType<String>(json, r'createdTime'),
        disableFileUpload: mapValueOfType<bool>(json, r'disableFileUpload'),
        displayName: mapValueOfType<String>(json, r'displayName'),
        embeddingProvider: mapValueOfType<String>(json, r'embeddingProvider'),
        enableTtsStreaming: mapValueOfType<bool>(json, r'enableTtsStreaming'),
        exampleQuestions: ExampleQuestion.listFromJson(json[r'exampleQuestions']),
        faviconUrl: mapValueOfType<String>(json, r'faviconUrl'),
        fileTree: TreeFile.fromJson(json[r'fileTree']),
        footerHtml: mapValueOfType<String>(json, r'footerHtml'),
        forbiddenWords: json[r'forbiddenWords'] is Iterable
            ? (json[r'forbiddenWords'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        frequency: mapValueOfType<int>(json, r'frequency'),
        hideThinking: mapValueOfType<bool>(json, r'hideThinking'),
        htmlTitle: mapValueOfType<String>(json, r'htmlTitle'),
        imageProvider: mapValueOfType<String>(json, r'imageProvider'),
        isDefault: mapValueOfType<bool>(json, r'isDefault'),
        knowledgeCount: mapValueOfType<int>(json, r'knowledgeCount'),
        limitMinutes: mapValueOfType<int>(json, r'limitMinutes'),
        logoUrl: mapValueOfType<String>(json, r'logoUrl'),
        memoryLimit: mapValueOfType<int>(json, r'memoryLimit'),
        messageCount: mapValueOfType<int>(json, r'messageCount'),
        modelProvider: mapValueOfType<String>(json, r'modelProvider'),
        name: mapValueOfType<String>(json, r'name'),
        navItems: json[r'navItems'] is Iterable
            ? (json[r'navItems'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        owner: mapValueOfType<String>(json, r'owner'),
        prompt: mapValueOfType<String>(json, r'prompt'),
        propertiesMap: Properties.mapFromJson(json[r'propertiesMap']),
        searchProvider: mapValueOfType<String>(json, r'searchProvider'),
        showAutoRead: mapValueOfType<bool>(json, r'showAutoRead'),
        speechToTextProvider: mapValueOfType<String>(json, r'speechToTextProvider'),
        splitProvider: mapValueOfType<String>(json, r'splitProvider'),
        state: mapValueOfType<String>(json, r'state'),
        storageProvider: mapValueOfType<String>(json, r'storageProvider'),
        storageSubpath: mapValueOfType<String>(json, r'storageSubpath'),
        suggestionCount: mapValueOfType<int>(json, r'suggestionCount'),
        textToSpeechProvider: mapValueOfType<String>(json, r'textToSpeechProvider'),
        themeColor: mapValueOfType<String>(json, r'themeColor'),
        title: mapValueOfType<String>(json, r'title'),
        vectorStoreId: mapValueOfType<String>(json, r'vectorStoreId'),
        vectorStores: json[r'vectorStores'] is Iterable
            ? (json[r'vectorStores'] as Iterable).cast<String>().toList(growable: false)
            : const [],
        welcome: mapValueOfType<String>(json, r'welcome'),
        welcomeText: mapValueOfType<String>(json, r'welcomeText'),
        welcomeTitle: mapValueOfType<String>(json, r'welcomeTitle'),
      );
    }
    return null;
  }

  static List<Store> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <Store>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = Store.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, Store> mapFromJson(dynamic json) {
    final map = <String, Store>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = Store.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of Store-objects as value to a dart map
  static Map<String, List<Store>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<Store>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = Store.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

